begin;
grant select,insert,update on public.authoring_jobs to service_role;
create table public.courses(id uuid primary key,title text not null check(length(title) between 1 and 200),grade integer not null check(grade between 6 and 9),owner_id uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now());
create table public.modules(id uuid primary key,course_id uuid not null references public.courses(id),title text not null,sort_order integer not null check(sort_order>=0));
create table public.module_lessons(module_id uuid not null references public.modules(id),lesson_id text not null references public.lessons(id),sort_order integer not null default 0,primary key(module_id,lesson_id));
create table public.enrollments(user_id uuid not null references auth.users(id),course_id uuid not null references public.courses(id),status text not null default 'active' check(status in ('active','completed')),primary key(user_id,course_id));
create index modules_course_idx on public.modules(course_id);
create index module_lessons_lesson_idx on public.module_lessons(lesson_id);
create index enrollments_course_idx on public.enrollments(course_id);
create index courses_owner_idx on public.courses(owner_id);
alter table public.courses enable row level security;
alter table public.modules enable row level security;
alter table public.module_lessons enable row level security;
alter table public.enrollments enable row level security;
create policy courses_read on public.courses for select to authenticated using((select lesson_private.role())='admin' or owner_id=(select auth.uid()) or exists(select 1 from public.enrollments e where e.user_id=(select auth.uid()) and e.course_id=id));
create policy courses_write on public.courses for insert to authenticated with check((select lesson_private.role())='admin' or ((select lesson_private.role())='author' and owner_id=(select auth.uid())));
create policy courses_update on public.courses for update to authenticated using((select lesson_private.role())='admin' or ((select lesson_private.role())='author' and owner_id=(select auth.uid()))) with check((select lesson_private.role())='admin' or ((select lesson_private.role())='author' and owner_id=(select auth.uid())));
create policy modules_read on public.modules for select to authenticated using(exists(select 1 from public.courses c where c.id=course_id));
create policy modules_write on public.modules for all to authenticated using(exists(select 1 from public.courses c where c.id=course_id and (c.owner_id=(select auth.uid()) or (select lesson_private.role())='admin'))) with check(exists(select 1 from public.courses c where c.id=course_id and (c.owner_id=(select auth.uid()) or (select lesson_private.role())='admin')));
create policy module_lessons_read on public.module_lessons for select to authenticated using(exists(select 1 from public.modules m where m.id=module_id));
create policy module_lessons_write on public.module_lessons for all to authenticated using(exists(select 1 from public.modules m join public.courses c on c.id=m.course_id where m.id=module_id and (c.owner_id=(select auth.uid()) or (select lesson_private.role())='admin'))) with check(exists(select 1 from public.modules m join public.courses c on c.id=m.course_id where m.id=module_id and (c.owner_id=(select auth.uid()) or (select lesson_private.role())='admin')));
create policy enrollment_read on public.enrollments for select to authenticated using(user_id=(select auth.uid()) or (select lesson_private.role())='admin');
create policy enrollment_admin on public.enrollments for all to authenticated using((select lesson_private.role())='admin') with check((select lesson_private.role())='admin');
grant select,insert,update on public.courses to authenticated;
grant select,insert,update,delete on public.modules,public.module_lessons,public.enrollments to authenticated;
create function lesson_private.set_role(p_user_id uuid,p_role text) returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or lesson_private.role() is distinct from 'admin' then raise exception 'Forbidden';end if;
 if p_user_id=auth.uid() and p_role<>'admin' then raise exception 'Cannot demote current administrator';end if;
 if p_role not in ('admin','author','student') then raise exception 'Invalid role';end if;
 insert into public.user_roles values(p_user_id,p_role) on conflict(user_id) do update set role=excluded.role;
 insert into public.audit_logs(actor_id,action,object_id) values(auth.uid(),'set_role:'||p_role,p_user_id::text);
end$$;
create function public.set_user_role(p_user_id uuid,p_role text) returns void language sql security invoker set search_path='' as $$select lesson_private.set_role(p_user_id,p_role)$$;
revoke all on function lesson_private.set_role(uuid,text),public.set_user_role(uuid,text) from public;
grant execute on function lesson_private.set_role(uuid,text),public.set_user_role(uuid,text) to authenticated;
create function lesson_private.new_profile() returns trigger language plpgsql security definer set search_path='' as $$begin
 insert into public.profiles(id,display_name) values(new.id,'Học viên');
 insert into public.user_roles(user_id,role) values(new.id,'student');return new;
end$$;
revoke all on function lesson_private.new_profile() from public,anon,authenticated;
create trigger lesson_profile_created after insert on auth.users for each row execute function lesson_private.new_profile();
commit;
